        return grid

    rows = len(grid)
    cols = len(grid[0])
    bg_color = grid[0][0] # Assume top-left is background

    # Breadth-First Search to mark all background pixels connected to the grid border
    visited = [[False] * cols for _ in range(rows)]
    queue = []

    # Add border pixels that match the background color
    for r in range(rows):
        if grid[r][0] == bg_color:
            queue.append((r, 0))
            visited[r][0] = True
        if grid[r][cols-1] == bg_color:
            queue.append((r, cols-1))
            visited[r][cols-1] = True

    for c in range(cols):
        if grid[0][c] == bg_color and not visited[0][c]:
            queue.append((0, c))
            visited[0][c] = True
        if grid[rows-1][c] == bg_color and not visited[rows-1][c]:
            queue.append((rows-1, c))
            visited[rows-1][c] = True

    # Directions for neighbors
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue:
        r, c = queue.pop(0)
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if not visited[nr][nc] and grid[nr][nc] == bg_color:
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    # Identify holes (background colored pixels not connected to the border)
    holes = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == bg_color and not visited[r][c]:
                holes.append((r, c))

    # Fill each hole with the color of its enclosing boundary
