                if grid[nr][nc] != bg_color:
                    neighbor_colors.add(grid[nr][nc])

        # Assuming the hole is surrounded by a single color
        fill_color = next(iter(neighbor_colors)) if neighbor_colors else bg_color
        grid[r][c] = fill_color

    return grid
